import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十卦 離 離為火 離上離下","description":"周易 - 第三十卦 離 離為火 離上離下","frontmatter":{"title":"第三十卦 離 離為火 離上離下","description":"周易 - 第三十卦 離 離為火 離上離下"},"headers":[],"relativePath":"classics/zhouyi/031.md","filePath":"classics/zhouyi/031.md"}'),l={name:"classics/zhouyi/031.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="離" tabindex="-1">離 <a class="header-anchor" href="#離" aria-label="Permalink to “離”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利貞，亨。畜牝牛，吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>離，麗也；日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正，故亨；是以畜牝牛吉也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>明兩作離，大人以繼明照於四方。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>履錯然，敬之無咎。象曰：履錯之敬， 以闢咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>黃離，元吉。象曰：黃離元吉，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>日昃之離，不鼓缶而歌，則大耋之嗟，兇。象曰：日昃之離，何可久也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>突如其來如，焚如，死如，棄如。象曰：突如其來如，無所容也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>出涕沱若，戚嗟若，吉。象曰：六五之吉，離王公也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>王用出徵，有嘉折首，獲其匪醜，無咎。象曰：王用出徵，以正邦也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
